import { Injectable } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { AppointmentCancelled, AppointmentScheduled, SchedulingEvents } from '@/contracts/scheduling.events';
import { VisitsService } from '../application/visits.service';

@Injectable()
export class SchedulingEventsListener {
  constructor(private readonly visits: VisitsService) {}

  @OnEvent(SchedulingEvents.AppointmentScheduled)
  async onAppointmentScheduled(event: AppointmentScheduled): Promise<void> {
    await this.visits.expectVisitor({
      appointmentId: event.appointmentId,
      personId: event.personId,
      practitionerId: event.practitionerId,
      expectedAt: new Date(event.startsAt),
    });
  }

  @OnEvent(SchedulingEvents.AppointmentCancelled)
  async onAppointmentCancelled(event: AppointmentCancelled): Promise<void> {
    await this.visits.cancelExpectedVisit(event.appointmentId);
  }
}
import { Controller, Get, HttpCode, Param, Post } from '@nestjs/common';
import { VisitsService } from '../application/visits.service';

@Controller('front-desk')
export class VisitsController {
  constructor(private readonly visits: VisitsService) {}

  @Post('visits/:appointmentId/check-in')
  @HttpCode(200)
  async checkIn(@Param('appointmentId') appointmentId: string) {
    const visit = await this.visits.checkIn(appointmentId);
    const queue = await this.visits.waitingQueue();
    const s = visit.toSnapshot();
    return {
      visitId: s.id,
      appointmentId: s.appointmentId,
      status: s.status,
      checkedInAt: s.checkedInAt?.toISOString() ?? null,
      queuePosition: queue.positionOf(s.id),
    };
  }

  @Get('queue')
  async queue() {
    const queue = await this.visits.waitingQueue();
    return queue.entries().map((visit, index) => {
      const s = visit.toSnapshot();
      return { position: index + 1, visitId: s.id, appointmentId: s.appointmentId, personId: s.personId };
    });
  }
}
import { Injectable, NotFoundException } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { FrontDeskEvents, VisitorCheckedIn } from '@/contracts/front-desk.events';
import { Clock, eventEnvelope, newId, PersonId, PractitionerId } from '@/shared-kernel';
import { Visit } from '../domain/visit';
import { VisitRepository } from '../domain/visit.repository';
import { WaitingQueue } from '../domain/waiting-queue';

export interface ExpectVisitorCommand {
  appointmentId: string;
  personId: PersonId;
  practitionerId: PractitionerId;
  expectedAt: Date;
}

@Injectable()
export class VisitsService {
  constructor(
    private readonly visits: VisitRepository,
    private readonly clock: Clock,
    private readonly events: EventEmitter2,
  ) {}

  async expectVisitor(command: ExpectVisitorCommand): Promise<void> {
    if (await this.visits.findByAppointmentId(command.appointmentId)) {
      return;
    }
    await this.visits.save(Visit.expect({ id: newId(), ...command }));
  }

  async cancelExpectedVisit(appointmentId: string): Promise<void> {
    const visit = await this.visits.findByAppointmentId(appointmentId);
    if (!visit) {
      return;
    }
    visit.cancel();
    await this.visits.save(visit);
  }

  async checkIn(appointmentId: string): Promise<Visit> {
    const visit = await this.visits.findByAppointmentId(appointmentId);
    if (!visit) {
      throw new NotFoundException(`No expected visit for appointment ${appointmentId}`);
    }
    visit.checkIn(this.clock.now());
    await this.visits.save(visit);

    const s = visit.toSnapshot();
    const event: VisitorCheckedIn = {
      ...eventEnvelope(this.clock.now()),
      visitId: s.id,
      appointmentId: s.appointmentId,
      personId: s.personId,
      practitionerId: s.practitionerId,
      checkedInAt: (s.checkedInAt as Date).toISOString(),
    };
    await this.events.emitAsync(FrontDeskEvents.VisitorCheckedIn, event);
    return visit;
  }

  async waitingQueue(): Promise<WaitingQueue> {
    return WaitingQueue.of(await this.visits.findCheckedIn());
  }
}
import type { PersonId, PractitionerId } from '@/shared-kernel';
import { CheckInNotAllowedError, VisitAlreadyCheckedInError } from './visit.errors';

export type VisitStatus = 'EXPECTED' | 'CHECKED_IN' | 'CANCELLED';

export interface VisitSnapshot {
  id: string;
  appointmentId: string;
  personId: PersonId;
  practitionerId: PractitionerId;
  expectedAt: Date;
  status: VisitStatus;
  checkedInAt: Date | null;
}

export interface ExpectVisitInput {
  id: string;
  appointmentId: string;
  personId: PersonId;
  practitionerId: PractitionerId;
  expectedAt: Date;
}

export class Visit {
  private constructor(private props: VisitSnapshot) {}

  static expect(input: ExpectVisitInput): Visit {
    return new Visit({ ...input, status: 'EXPECTED', checkedInAt: null });
  }

  static restore(snapshot: VisitSnapshot): Visit {
    return new Visit({ ...snapshot });
  }

  get id(): string {
    return this.props.id;
  }

  get status(): VisitStatus {
    return this.props.status;
  }

  get checkedInAt(): Date | null {
    return this.props.checkedInAt;
  }

  checkIn(now: Date): void {
    if (this.props.status === 'CHECKED_IN') {
      throw new VisitAlreadyCheckedInError();
    }
    if (this.props.status !== 'EXPECTED') {
      throw new CheckInNotAllowedError(this.props.status);
    }
    this.props.status = 'CHECKED_IN';
    this.props.checkedInAt = now;
  }

  cancel(): void {
    if (this.props.status === 'EXPECTED') {
      this.props.status = 'CANCELLED';
    }
  }

  toSnapshot(): VisitSnapshot {
    return { ...this.props };
  }
}
import type { Visit } from './visit';

export class WaitingQueue {
  private constructor(private readonly visits: readonly Visit[]) {}

  static of(visits: readonly Visit[]): WaitingQueue {
    const waiting = visits
      .filter((visit) => visit.status === 'CHECKED_IN' && visit.checkedInAt !== null)
      .sort((a, b) => (a.checkedInAt as Date).getTime() - (b.checkedInAt as Date).getTime());
    return new WaitingQueue(waiting);
  }

  get size(): number {
    return this.visits.length;
  }

  positionOf(visitId: string): number | null {
    const index = this.visits.findIndex((visit) => visit.id === visitId);
    return index === -1 ? null : index + 1;
  }

  entries(): readonly Visit[] {
    return this.visits;
  }
}
import type { Visit } from './visit';

export abstract class VisitRepository {
  abstract findByAppointmentId(appointmentId: string): Promise<Visit | null>;
  abstract findCheckedIn(): Promise<Visit[]>;
  abstract save(visit: Visit): Promise<void>;
}
