import { BadRequestException, Body, Controller, Get, HttpCode, Param, Post, Query } from '@nestjs/common';
import { EncountersService } from '../application/encounters.service';
import type { Encounter } from '../domain/encounter';

interface CompleteEncounterBody {
  notes?: string;
  diagnosisCodes?: string[];
  procedureCodes?: string[];
}

@Controller('clinical/encounters')
export class EncountersController {
  constructor(private readonly encounters: EncountersService) {}

  @Get()
  async findByAppointment(@Query('appointmentId') appointmentId?: string) {
    if (!appointmentId) {
      throw new BadRequestException('appointmentId is required');
    }
    return toResponse(await this.encounters.findByAppointment(appointmentId));
  }

  @Post(':id/start')
  @HttpCode(200)
  async start(@Param('id') id: string) {
    return toResponse(await this.encounters.start(id));
  }

  @Post(':id/complete')
  @HttpCode(200)
  async complete(@Param('id') id: string, @Body() body: CompleteEncounterBody) {
    return toResponse(
      await this.encounters.complete(id, {
        notes: body.notes ?? '',
        diagnosisCodes: body.diagnosisCodes ?? [],
        procedureCodes: body.procedureCodes ?? [],
      }),
    );
  }
}

function toResponse(encounter: Encounter) {
  const s = encounter.toSnapshot();
  return {
    id: s.id,
    appointmentId: s.appointmentId,
    patientId: s.patientId,
    status: s.status,
    procedureCodes: s.procedureCodes,
    diagnosisCodes: s.diagnosisCodes,
  };
}
import { Injectable, NotFoundException } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { ClinicalEvents, EncounterCompleted } from '@/contracts/clinical.events';
import { Clock, eventEnvelope, newId, PersonId, PractitionerId } from '@/shared-kernel';
import { Encounter, EncounterRecord } from '../domain/encounter';
import { EncounterRepository } from '../domain/encounter.repository';

export interface RegisterArrivalCommand {
  appointmentId: string;
  patientId: PersonId;
  practitionerId: PractitionerId;
  arrivedAt: Date;
}

@Injectable()
export class EncountersService {
  constructor(
    private readonly encounters: EncounterRepository,
    private readonly clock: Clock,
    private readonly events: EventEmitter2,
  ) {}

  async registerArrival(command: RegisterArrivalCommand): Promise<void> {
    if (await this.encounters.findByAppointmentId(command.appointmentId)) {
      return;
    }
    await this.encounters.save(Encounter.open({ id: newId(), ...command }));
  }

  async start(encounterId: string): Promise<Encounter> {
    const encounter = await this.load(encounterId);
    encounter.start(this.clock.now());
    await this.encounters.save(encounter);
    return encounter;
  }

  async complete(encounterId: string, record: EncounterRecord): Promise<Encounter> {
    const encounter = await this.load(encounterId);
    encounter.complete(record, this.clock.now());
    await this.encounters.save(encounter);

    const s = encounter.toSnapshot();
    const event: EncounterCompleted = {
      ...eventEnvelope(this.clock.now()),
      encounterId: s.id,
      appointmentId: s.appointmentId,
      personId: s.patientId,
      procedureCodes: s.procedureCodes,
      completedAt: (s.completedAt as Date).toISOString(),
    };
    await this.events.emitAsync(ClinicalEvents.EncounterCompleted, event);
    return encounter;
  }

  async findByAppointment(appointmentId: string): Promise<Encounter> {
    const encounter = await this.encounters.findByAppointmentId(appointmentId);
    if (!encounter) {
      throw new NotFoundException(`No encounter for appointment ${appointmentId}`);
    }
    return encounter;
  }

  private async load(encounterId: string): Promise<Encounter> {
    const encounter = await this.encounters.findById(encounterId);
    if (!encounter) {
      throw new NotFoundException(`Encounter ${encounterId} not found`);
    }
    return encounter;
  }
}
import type { PersonId, PractitionerId } from '@/shared-kernel';
import { InvalidEncounterTransitionError, ProcedureRequiredError } from './encounter.errors';

export type EncounterStatus = 'WAITING' | 'IN_PROGRESS' | 'COMPLETED';

export interface EncounterSnapshot {
  id: string;
  appointmentId: string;
  patientId: PersonId;
  practitionerId: PractitionerId;
  status: EncounterStatus;
  notes: string | null;
  diagnosisCodes: string[];
  procedureCodes: string[];
  arrivedAt: Date;
  startedAt: Date | null;
  completedAt: Date | null;
}

export interface PatientArrival {
  id: string;
  appointmentId: string;
  patientId: PersonId;
  practitionerId: PractitionerId;
  arrivedAt: Date;
}

export interface EncounterRecord {
  notes: string;
  diagnosisCodes: string[];
  procedureCodes: string[];
}

export class Encounter {
  private constructor(private props: EncounterSnapshot) {}

  static open(arrival: PatientArrival): Encounter {
    return new Encounter({
      ...arrival,
      status: 'WAITING',
      notes: null,
      diagnosisCodes: [],
      procedureCodes: [],
      startedAt: null,
      completedAt: null,
    });
  }

  static restore(snapshot: EncounterSnapshot): Encounter {
    return new Encounter({ ...snapshot });
  }

  get id(): string {
    return this.props.id;
  }

  get status(): EncounterStatus {
    return this.props.status;
  }

  start(now: Date): void {
    if (this.props.status !== 'WAITING') {
      throw new InvalidEncounterTransitionError('start', this.props.status);
    }
    this.props.status = 'IN_PROGRESS';
    this.props.startedAt = now;
  }

  complete(record: EncounterRecord, now: Date): void {
    if (this.props.status !== 'IN_PROGRESS') {
      throw new InvalidEncounterTransitionError('complete', this.props.status);
    }
    const procedureCodes = normalizeCodes(record.procedureCodes);
    if (procedureCodes.length === 0) {
      throw new ProcedureRequiredError();
    }
    this.props.status = 'COMPLETED';
    this.props.notes = record.notes;
    this.props.diagnosisCodes = normalizeCodes(record.diagnosisCodes);
    this.props.procedureCodes = procedureCodes;
    this.props.completedAt = now;
  }

  toSnapshot(): EncounterSnapshot {
    return {
      ...this.props,
      diagnosisCodes: [...this.props.diagnosisCodes],
      procedureCodes: [...this.props.procedureCodes],
    };
  }
}

function normalizeCodes(codes: readonly string[]): string[] {
  return [...new Set(codes.map((code) => code.trim()).filter((code) => code.length > 0))];
}
